def match(orders):
    trades = []
    buy_book = []  # min-heap by price (ascending), then by arrival time
    sell_book = []  # max-heap by price (descending), then by arrival time

    # Track order state: id -> (side, original_price, remaining_qty, arrival_index)
    order_state = {}
    arrival_index = 0

    for order in orders:
        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_state:
                side, price, qty, _ = order_state[order_id]
                if qty > 0:  # Only cancel if not fully filled
                    del order_state[order_id]
                    # Remove from book
                    if side == 'buy':
                        buy_book[:] = [(p, idx, oid, q) for p, idx, oid, q in buy_book if oid != order_id]
                    else:
                        sell_book[:] = [(p, idx, oid, q) for p, idx, oid, q in sell_book if oid != order_id]
            continue

        order_type = order[0]
        order_id = order[1]
        side = order[2]
        qty = order[4] if len(order) > 4 else order[3]
        price = order[3] if len(order) > 4 else None

        arrival_index += 1

        if order_type == 'market':
            price = float('inf') if side == 'buy' else 0

        # Match against existing orders
        if side == 'buy':
            # Match against sell_book (highest price first, then earliest)
            while qty > 0 and sell_book:
                # Get best sell order (lowest price, earliest arrival)
                sell_book.sort(key=lambda x: (x[0], x[1]))
                best_sell_price, best_sell_idx, best_sell_id, best_sell_qty = sell_book[0]

                if best_sell_price <= price:
                    trade_qty = min(qty, best_sell_qty)
                    trades.append([order_id, best_sell_id, best_sell_price, trade_qty])

                    qty -= trade_qty
                    best_sell_qty -= trade_qty

                    if best_sell_qty == 0:
                        sell_book.pop(0)
                        order_state[best_sell_id] = (order_state[best_sell_id][0], order_state[best_sell_id][1], 0, order_state[best_sell_id][3])
                    else:
                        sell_book[0] = (best_sell_price, best_sell_idx, best_sell_id, best_sell_qty)
                else:
                    break
        else:
            # Match against buy_book (lowest price first, then earliest)
            while qty > 0 and buy_book:
                # Get best buy order (highest price, earliest arrival)
                buy_book.sort(key=lambda x: (-x[0], x[1]))
                best_buy_price, best_buy_idx, best_buy_id, best_buy_qty = buy_book[0]

                if best_buy_price >= price:
                    trade_qty = min(qty, best_buy_qty)
                    trades.append([best_buy_id, order_id, best_buy_price, trade_qty])

                    qty -= trade_qty
                    best_buy_qty -= trade_qty

                    if best_buy_qty == 0:
                        buy_book.pop(0)
                        order_state[best_buy_id] = (order_state[best_buy_id][0], order_state[best_buy_id][1], 0, order_state[best_buy_id][3])
                    else:
                        buy_book[0] = (best_buy_price, best_buy_idx, best_buy_id, best_buy_qty)
                else:
                    break

        # Add to book if limit order with remaining qty, or ioc/market with remaining qty
        if order_type == 'limit' and qty > 0:
            order_state[order_id] = (side, price, qty, arrival_index)
            if side == 'buy':
                buy_book.append((price, arrival_index, order_id, qty))
            else:
                sell_book.append((price, arrival_index, order_id, qty))
        elif order_type in ['ioc', 'market']:
            # IOC and market orders don't rest
            if qty > 0:
                order_state[order_id] = (side, price if order_type == 'ioc' else None, 0, arrival_index)
        else:
            order_state[order_id] = (side, price, qty, arrival_index)

    return trades

